            "timeText": {
              "type": "string",
              "description": "待办任务提醒时间展示文本。",
              "sampleValue": "18:30"
            },
            "urgency": {
              "type": "string",
              "description": "待办任务紧迫程度短标签。",
              "sampleValue": "紧急"
            },
            "done": {
              "type": "boolean",
              "description": "待办任务是否已完成。",
              "sampleValue": false
            }
          }
        }
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "29°"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

